insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-reread-keep-the-better-s683','decision','A reread keeps the better record, within $40 a college','S683 conductor: the reread plan''s paid-step condition failed as written (previews list programs outside the aim rows, many passing). Decided: pay within $40 a college, then kb/_program_reread_keep_better.py restores any re-read that is worse than the filed record or does not name its own program. Two review rounds, 6 findings fixed. Sam or COBIx may reverse this.',array['program-requirements','reread','conductor'],'proposed','kb/program_requirements_reread_plan_s683.json; claude/reread-wave-s683','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('d-reread-then-load-s683','decision','A reread never inserts: follow every reread with a load','S683 conductor: the reread step replaces filed rows and inserts none; a program the reread finds with no live row is reported absent. Every reread at a college is followed by a load, which inserts those. Tonight 133 rows replaced, 72 inserted at 15 colleges.',array['program-requirements','reread','procedure'],'proposed','claude/reread-wave-s683; claude/harvest-wave-s683','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('d-a4-apply-with-pathways-reader-s683','decision','#3508''s A4 write landed with the CPL Pathways reader for a together group','S683 conductor: #3508''s corrective write applied only with its display reader: CPL Pathways reads a together group the write creates, in the same branch. Findings 1 and 2 fixed first; the plan grew to 14 rows (13 carried plus Long Beach City 44747). Pre-read run 44473918412 clean, apply run 44483137614 returned 14.',array['program-requirements','cheap-piles','cpl-pathways'],'proposed','#3508; the wave','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('d-note-pair-off-s683','decision','NOTE_PAIR_ON is off: the pair rule checked itself against its own pattern','S683 conductor (#3508): NOTE_PAIR_ON = False. Its self-check took the expected answer from the rule''s own pattern, so it could not fail. Six records the rule would pair start a hand-held list for a person. The rule turns on only with a self-check against an independent source.',array['program-requirements','cheap-piles','self-check'],'proposed','#3508','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('d-desert-skipped-s683','decision','College of the Desert skipped in the reread wave','S683 conductor: College of the Desert''s preview listed 72 programs, 63 passing, and none of the plan''s aim rows, so no paid read ran there. Its branch claude/reread-college-of-the-desert-s683 carries the preview and no PR.',array['program-requirements','reread'],'proposed','claude/reread-college-of-the-desert-s683','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('d-trigger-branches-no-pr-s683','decision','On a saturated runner pool a trigger-only branch carries no PR','S683 conductor: with the runner pool saturated, a branch that exists only to trigger a run (a preview, a reread) opens no pull request, since each PR push adds CI to the queue. The handoff''s ledger names every such branch and its state instead.',array['conductor','runner-pool','ci'],'proposed','docs/session_684_handoff.md','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('d-lane-workers-dispatch-reread-load-s683','decision','Lane workers may dispatch the reread and the load once the script is reviewed','S683 conductor: a narrow lift. Once kb/_program_reread_keep_better.py had passed its second reader, the two lane workers dispatched the reread and the load at their own colleges, one college at a time, under the $40 meter. No other write moved to the workers.',array['conductor','program-requirements','workers'],'proposed','claude/reread-wave-s683; claude/harvest-wave-s683','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('d-slimming-to-plain-session-s683','decision','The brief''s repo-slimming items go to a plain session','S683 conductor: START_HERE.md with the CLAUDE.md cut, the session trim, and timed workflows committing once a day go to a plain session. Sam''s routine prompt of 2026-11-17 keeps conductor runs to collection, and the cut moves doctrine every session loads. COBIx is told in handoff 684.',array['conductor','repo-size','scheduled-sessions'],'proposed','docs/session_684_handoff.md; #3358','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('d-conductor-model-as-configured-s683','decision','The conductor ran on the model the routine configures (Fable 5.2)','S683: the transcripts show claude-fable-5-2 on every conductor call. The brief expected the routine''s form to set Opus 5.5 for tonight''s side of the comparison; it did not, so tonight is a second Fable 5.2 night. The session cannot change its own model; the form is Sam''s to change.',array['conductor','model','scheduled-sessions'],'proposed','docs/session_684_handoff.md','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('p-runner-pool-starves-migrate-s683','pitfall','Seventeen dispatches and a dozen PR pushes starve the runner pool','S683: 17 workflow dispatches and about a dozen PR pushes inside 40 minutes saturated the runner pool. Each supabase-migrate run then waited 30 to 40 minutes for a runner and CI ran about 90 minutes. Dispatch at most 10 colleges a batch, batch pushes, and open no PR for a trigger-only branch.',array['runner-pool','ci','conductor','pitfall'],'proposed','docs/reference/conductor_mode.md','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('p-ci-cancel-agent-denied-s683','pitfall','The permission check refused an agent briefed to cancel superseded CI runs','S683: an agent briefed to cancel CI runs on carried and superseded branches was refused by the permission check. The refusal was recorded and not routed around; the runs finished on their own.',array['ci','permissions','pitfall'],'proposed','docs/session_684_handoff.md','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('p-execute-sql-stalled-s683','pitfall','One Execute SQL read returned 55 minutes late','S683: one execute_sql read sent at 08:15Z returned at 09:10Z. While it waited the conductor could not act, and the declaration PR''s half-hour refresh lapsed once. The headline pair and the harvest row were not read. Batch reads into one call and keep a heartbeat that does not wait on the SQL tool.',array['supabase','conductor','pitfall'],'proposed','docs/session_684_handoff.md','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('p-fixture-by-rule-vanishes-s683','pitfall','A test that picks its fixture from live rows fails when a person settles them','S683: tests/side_by_side_test.py picked its fixture by rule from today''s held cards. Sam settled 28 of 31 on 2026-11-18, the rule found nothing, and main went red after the daily run. The same cause reached exhibits_side_by_side.test.js and issuer_tags.test.js. Fix #3542; a fixture needs a committed fallback.',array['tests','cer-procedures','pitfall'],'proposed','#3542','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('f-reread-replaces-labeled-rows-s683','fact','Tonight''s rereads replaced rows the named-gaps apply had labeled','S683: the reread wave replaced rows #3497''s apply had given a named-gap label, so the label went with the old record: live catalog_figures_differ reads 19 of the 21 it had. A named-gaps pass over the re-read records is due before the next display build.',array['program-requirements','named-gaps','reread'],'proposed','claude/reread-wave-s683; #3497','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('f-hand-fetched-colleges-read-fine-s683','fact','None of the eight hand-fetched colleges is refused by the program reader','S683: the eight colleges on the hand-fetch list read fine through the program reader; their blocks belong to the outline reader. West Los Angeles, Trade-Technical, Pierce, Mission, East Los Angeles and El Camino were read and loaded. #3536 stops the reader at a WAF challenge or a challenged robots.txt.',array['program-requirements','blocked-sources'],'proposed','#3536; claude/harvest-wave-s683','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('m-chabot-loaded-both-kinds-s683','milestone','Chabot outlines loaded, SLOs and objectives apart','S683: Chabot re-read with the fixed reader (read 44472580748, 3 parts), standing test 26 of 26 on the branch, then load run 44484699264: 1,013 slo and 1,013 objective rows inserted, ids 34631 to 36656, none kept or skipped. course_outcomes 30,321 to 32,347.',array['course-outcomes','chabot','milestone'],'proposed','kb/receipts/course_outcomes_chabot_44484699264.json','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('m-named-gaps-99-applied-s683','milestone','#3497''s 99-row named-gaps plan applied','S683, under Sam''s go of 2026-11-18 relayed by COBIx: #3497''s 99-row named-gaps plan applied. Pre-read run 44472420629 clean; apply run 44474531589 returned 99, none skipped.',array['program-requirements','named-gaps','milestone'],'proposed','#3497','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('m-a4-14-applied-s683','milestone','#3508''s A4 write applied, 14 rows','S683, under Sam''s go of 2026-11-18 relayed by COBIx: #3508 after two review rounds, 14 rows (13 carried plus Long Beach City 44747). Pre-read run 44473918412 clean; apply run 44483137614 returned 14.',array['program-requirements','cheap-piles','milestone'],'proposed','#3508','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19'),
('m-reread-wave-15-colleges-s683','milestone','The reread wave: 15 colleges, 133 rows replaced, 72 inserted','S683: rereads then loads at 15 colleges, every receipt error null. Cheap-piles lane (Mendocino, CCSF, Santa Rosa, Compton, Foothill, Porterville, Citrus, San Bernardino Valley, Moorpark): 114 replaced, 53 inserted. Collection lane (six LA-area colleges and El Camino): 19 and 19. program_requirement_records 18,240 to 18,312; filed run costs $25.20.',array['program-requirements','reread','milestone'],'proposed','claude/reread-wave-s683; claude/harvest-wave-s683','SkyNuthatch (S683), the conductor',null,'SkyNuthatch (S683)',date '2026-11-19')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
